import React from 'react';
import {magic} from '@utils';
import {Box, Typography} from '@mui/material';
import Statistic from '../Statistic';
import cn from 'classnames';
import s from './Groups.scss';

const Group = ({
  group,
  disabled,
  allView,
  checkedView,
  allByFilter,
  checkedByFilter,
  activeGroup,
  setActiveGroup
}) => {
  const classNames = cn(
    {
      [s.active]: group === activeGroup,
      [s.disabled]: disabled
    },
    s.button
  );

  const onClick = disabled ?
    null :
    () => setActiveGroup(group);

  return (
    <Box
      className={classNames}
      onClick={onClick}
    >
      <Typography className={s.groupName}>
        {group}
      </Typography>
      {
        !disabled && (
          <Statistic
            received={checkedByFilter}
            receivedAll={checkedView}
            filtered={allByFilter}
            all={allView}
          />
        )
      }
    </Box>
  );
};

const mapStore = ({EldenRingStore}) => {
  return {
    activeGroup: EldenRingStore.activeGroup,
    setActiveGroup: EldenRingStore.setActiveGroup
  };
};

export default magic(Group, {store: mapStore, styles: s});
