import React from 'react';
import {magic} from '@utils';
import Filter from './Filter';
import Groups from './Groups';
import Categories from './Categories';
import Items from './Items';
import {Box} from '@mui/material';
import s from './style.scss';

const EldenRingTracking = ({saveToDataBase}) => {
  const ref = React.useRef(null);

  React.useEffect(() => {
    ref.current = setInterval(saveToDataBase, 10 * 60 * 1000);

    return () => {
      if (ref.current) {
        clearInterval(ref.current);
      }
    };
  }, []);

  return (
    <Box className={s.container}>
      <Box className={s.leftColumn}>
        <Filter />
        <Groups />
      </Box>
      <Categories />
      <Items />
    </Box>
  );
};

const mapStore = ({EldenRingStore}) => {
  return {
    saveToDataBase: EldenRingStore.saveToDataBase
  };
};

export default magic(EldenRingTracking, {store: mapStore, styles: s});