import React from 'react';
import {Autocomplete, TextField} from '@mui/material';
import {IAnyObject} from '@types';

const Combobox = ({name, value, options, onChange, isMulti, placeholder}: ComboboxProps) => (
  <Autocomplete
    value={value}
    options={options}
    onChange={(_, val) => onChange({target: {name, value: val}})}
    multiple={isMulti}
    limitTags={2}
    size={'small'}
    filterSelectedOptions={true}
    renderInput={
      (params) => (
        <TextField
          {...params}
          label={name}
          name={name}
          placeholder={placeholder}
        />
      )
    }
  />
);

type ComboboxProps = {
  name?: string;
  value: string | number | IAnyObject | IAnyObject[];
  options: string[];
  onChange: ({target}: IAnyObject) => void;
  placeholder?: string;
  isMulti?: boolean;
}

export default Combobox;