import {makeObservable, observable, action, computed, when, reaction} from 'mobx';
import {ER, IDS, groupBy, notify, keyboardConvert} from '@utils';
import {get, set} from '@api';
import {
  ERItem,
  ERFilter,
  FilterValue,
  IAnyObject,
  Count,
  CategoryCount,
  GroupCount
} from '@types';

const URL_PREFIX = 'https://eldenring.wiki.fextralife.com/';

class EldenRingStore {
  UserStore;

  groups: string[] = [];
  categories: string[] = [];
  regions: string[] = [];
  activeGroup: string = 'Melee Armaments';
  activeCategory: string = 'Daggers';

  categoriesByGroup: {[key: string]: string} = {};

  items: ERItem[] = [];
  filter: ERFilter = {};
  checked: Set<string> = new Set();
  hidden: Set<string> = new Set();

  disposers = [];

  constructor({UserStore}) {
    makeObservable(this, {
      groups: observable,
      categories: observable,
      regions: observable,
      activeGroup: observable,
      activeCategory: observable,

      items: observable,
      filter: observable,
      checked: observable,
      hidden: observable,

      filteredItems: computed,
      countAllByGroup: computed,
      categoryItems: computed,

      setActiveGroup: action,
      setActiveCategory: action,
      setItems: action,
      setFilter: action,
      setChecked: action,
      setHidden: action,

      setFilterValue: action,
      setCheckValue: action,
      toggleHide: action
    });

    this.UserStore = UserStore;

    this.disposers.push(
      when(
        () => this.UserStore.user,
        () => this.init()
      ),
      reaction(
        () => this.activeGroup,
        () => {
          const [firstCategory] = this.categoriesByGroup[this.activeGroup];

          this.setActiveCategory(firstCategory);
        }
      )
    );
  }

  // GETTERS AND COMPUTES

  get filteredItems() {
    const {items, filter} = this;

    return items.filter((item: ERItem) => {
      const states: boolean[] = [];
      const hiddenProperties: boolean[] = [];

      if (filter.group?.length) {
        states.push(
          filter.group.includes(item.group)
        );
      }

      if (filter.category?.length) {
        states.push(
          filter.category.includes(item.category)
        );
      }

      if (filter.region?.length) {
        states.push(
          !filter.region.some((region) =>
            item.regions ?
              item.regions.includes(region) :
              true)
        );
      }

      if (filter.name) {
        const [original, converted] = keyboardConvert(filter.name)

        const itemName: string = item.name.toLowerCase();
        const originalSearch: string = original.toLowerCase();
        const convertedSearch: string = converted?.toLowerCase();

        states.push(
          itemName.includes(originalSearch) ||
          itemName.includes(convertedSearch)
        );
      }

      if (filter.hideDlc) {
        states.push(!item.dlc);
      }

      if (item.purchaseFrom) {
        hiddenProperties.push(filter.hidePurchaseFrom);
      }

      if (item.rewardByNpc) {
        hiddenProperties.push(filter.hideRewardByNpc);
      }

      if (item.foundAt) {
        hiddenProperties.push(filter.hideFoundAt);
      }

      if (item.dropByEnemies) {
        hiddenProperties.push(filter.hideDropByEnemies);
      }

      if (item.alwaysDrop) {
        hiddenProperties.push(filter.hideAlwaysDrop);
      }

      if (item.missable) {
        hiddenProperties.push(filter.hideMissable);
      }

      if (item.crafted) {
        hiddenProperties.push(filter.hideCrafted);
      }

      if (item.obtained) {
        hiddenProperties.push(filter.hideObtained);
      }

      const isMainFilter = states.length ? states.every(Boolean) : true;
      const isHidden = !(hiddenProperties.length && hiddenProperties.every(Boolean));

      return isMainFilter && isHidden;
    });
  }

  get countAllByGroup() {
    return this.getCount(this.items);
  }

  get countFilteredByGroup() {
    return this.getCount(this.filteredItems);
  }

  get filteredItemsByCategory() {
    return groupBy(this.filteredItems, 'category');
  }

  get categoryItems() {
    return this.filteredItemsByCategory[this.activeCategory] || [];
  }

  // ACTIONS

  setActiveGroup = (group: string) => {
    this.activeGroup = group;
  };

  setActiveCategory = (category: string) => {
    this.activeCategory = category;
  };

  setItems = (items: ERItem[]) => {
    this.items = items;
  };

  setFilter = (filter: ERFilter | undefined) => {
    this.filter = filter || {};
  };

  setChecked = (checked: Set<string> | undefined) => {
    this.checked = checked || new Set();
  };

  setHidden = (hidden: Set<string> | undefined) => {
    this.hidden = hidden || new Set();
  };

  setFilterValue = (name: string, value: FilterValue) => {
    if (name === 'group' && this.filter.category?.length) {
      const newCategoryNames = this.categories?.reduce((result, category) => {
        if (Array.isArray(value) && value.includes(category)) {
          result.push(category);
        }

        return result;
      }, [] as string[]);

      this.filter.category = this.filter.category
        .filter((category) => newCategoryNames.includes(category));
    }

    this.filter[name] = value;

    localStorage.setItem('filter', JSON.stringify(this.filter));
  };

  setCheckValue = ({target}) => {
    const {checked} = this;

    checked.has(target.name) ?
      checked.delete(target.name) :
      checked.add(target.name);

    this.checked = checked;

    localStorage.setItem('checked', JSON.stringify([...checked]));
  };

  toggleHide = (name: string) => {
    const {hidden} = this;

    hidden.has(name) ?
      hidden.delete(name) :
      hidden.add(name);

    this.hidden = hidden;

    localStorage.setItem('hidden', JSON.stringify([...hidden]));
  };

  // REQUESTS

  setter = async(collection: string, data: ERFilter | string[]) => {
    const {user} = this.UserStore;

    if (!user?.email) {
      return notify({
        variant: 'error',
        message: 'User not found'
      });
    }

    await set(collection, user.email, {data});
  };

  getter = async(collection: string) => {
    const {user} = this.UserStore;

    if (!user?.email) {
      notify({
        variant: 'error',
        message: 'User not found'
      });

      return null;
    }

    const result: IAnyObject = await get(collection, user.email);

    return result?.data;
  };

  getFromDatabase = async() => {
    try {
      const [
        filter,
        hidden,
        checked
      ] = await Promise.all([
        this.getter('filter'),
        this.getter('hidden'),
        this.getter('checked')
      ]);

      if (filter) {
        this.setFilter(filter);

        localStorage.setItem('filter', JSON.stringify(filter));
      }

      if (hidden) {
        this.setHidden(new Set(hidden));

        localStorage.setItem('hidden', JSON.stringify(hidden));
      }

      if (checked) {
        this.setChecked(new Set(checked));

        localStorage.setItem('checked', JSON.stringify(checked));
      }

      notify({
        variant: 'success',
        message: 'Data loaded successfully'
      });
    } catch(err) {
      notify({
        variant: 'error',
        message: 'Failed to load data'
      });
    }
  };

  saveToDataBase = async() => {
    const {
      filter,
      hidden,
      checked
    } = this;

    try {
      await Promise.all([
        this.setter('filter', filter),
        this.setter('hidden', [...hidden]),
        this.setter('checked', [...checked])
      ]);

      notify({
        variant: 'success',
        message: 'Data saved successfully'
      });
    } catch(err) {
      notify({
        variant: 'error',
        message: 'Failed to save data'
      });
    }
  };

  // OTHER

  init = async() => {
    this.setItems(ER);

    // const promises = [];
    //
    // for (const item of ER) {
    //   if (item.group === 'Melee Armaments') {
    //     const newItem = {...item};
    //
    //     newItem.affinity = IDS.weapons[item.group]?.[item.category]?.[item.name] || {};
    //
    //     promises.push(set('items', item.name, newItem));
    //   }
    // }
    //
    // await Promise.all(promises);

    const {
      groups,
      categories,
      regions,
      categoriesByGroup
    } = ER.reduce((result, {group, category, regions: itemRegions}: ERItem) => {
      result.groups.add(group);
      result.categories.add(category);

      if (itemRegions) {
        itemRegions.forEach((region) => {
          result.regions.add(region);
        });
      }

      result.categoriesByGroup[group] = result.categoriesByGroup[group] || [];

      if (!result.categoriesByGroup[group].includes(category)) {
        result.categoriesByGroup[group].push(category);
      }

      return result;
    }, {
      groups: new Set(),
      categories: new Set(),
      regions: new Set(),
      categoriesByGroup: {}
    } as {
      groups: Set<string>;
      categories: Set<string>;
      regions: Set<string>;
      categoriesByGroup: {[key: string]: string}
    });

    this.groups = [...groups];
    this.categories = [...categories];
    this.regions = [...regions];
    this.categoriesByGroup = categoriesByGroup;

    const filter = JSON.parse(localStorage.getItem('filter') || null);
    const checked = JSON.parse(localStorage.getItem('checked') || null);
    const hidden = JSON.parse(localStorage.getItem('hidden') || null);

    this.setFilter(filter || await this.getter('filter'));
    this.setHidden(new Set(hidden || await this.getter('hidden') || []));
    this.setChecked(new Set(checked || await this.getter('checked') || []));
  };

  link = (name: string): string => `${URL_PREFIX}${name}`;

  getCount = (items: ERItem[]) => items
    .reduce((result: GroupCount, {group, category, name}) => {
      const isChecked = this.checked.has(name);

      if (result[group]) {
        result[group].count++;

        if (isChecked) {
          result[group].checked++;
        }

        if (result[group][category]) {
          result[group][category].count++;

          if (isChecked) {
            result[group][category].checked++;
          }
        } else {
          result[group][category] = {
            count: 1,
            checked: isChecked ? 1 : 0
          };
        }

      } else {
        result[group] = {
          count: 1,
          checked: isChecked ? 1 : 0,
          [category]: {
            count: 1,
            checked: isChecked ? 1 : 0
          }
        } as Count & CategoryCount;
      }

      return result;
    }, {} as GroupCount);
}

export default EldenRingStore;
