import React from 'react';
import {magic} from '@utils';
import {Paper} from '@mui/material';
import Group from './Group';
import s from './Groups.scss';

const Groups = ({
  groups,
  countAllByGroup,
  countFilteredByGroup
}) => {
  return (
    <Paper
      elevation={0}
      className={s.groups}
    >
      {
        groups.map((group) => {
          const allView = countAllByGroup[group].count;
          const allByFilter = countFilteredByGroup[group]?.count;

          return (
            <Group
              key={group}
              group={group}
              disabled={!allByFilter}
              allView={allView}
              checkedView={countAllByGroup[group].checked}
              allByFilter={allView !== allByFilter ? allByFilter : null}
              checkedByFilter={countFilteredByGroup[group]?.checked}
            />
          );
        })
      }
    </Paper>
  );
};

const mapStore = ({EldenRingStore}) => {
  return {
    groups: EldenRingStore.groups,
    countAllByGroup: EldenRingStore.countAllByGroup,
    countFilteredByGroup: EldenRingStore.countFilteredByGroup
  };
};

export default magic(Groups, {store: mapStore, styles: s});