import ROUTES from './consts/routes.json';
import ER from './consts/ER.json';
import IDS from './consts/IDS';
import FIREBASE_ERRORS from './consts/firebaseErrors.json';
import {magic} from './magic';
import {keyboardConvert} from './keyboardConvert';
import {getPluralForm} from './getPluralForm';
import {coupleBy} from './coupleBy';
import {array2Object} from './array2Object';
import {groupBy} from './groupBy';
import * as fp from './fp';
import {enqueueSnackbar} from 'notistack';

const hasValue = (value) => value !== '' && value !== null && value !== undefined;

/**
 * Выводит сообщение пользователю
 * @param {string} message - Текст сообщения
 * @param {'default' | 'error' | 'success' | 'warning' | 'info'} variant - Тип сообщения
 * @returns {*}
 */
const notify = ({message, variant}) => enqueueSnackbar({message, variant, dense: true});

export {
  ROUTES,
  ER,
  IDS,
  FIREBASE_ERRORS,
  magic,
  keyboardConvert,
  hasValue,
  getPluralForm,
  coupleBy,
  array2Object,
  groupBy,
  fp,
  notify
};