import React from 'react';
import {magic} from '@utils';
import {Paper} from '@mui/material';
import Category from './Category';
import s from './Categories.scss';

const Categories = ({
  activeGroup,
  categoriesByGroup,
  countAllByGroup,
  countFilteredByGroup
}) => {
  return (
    <Paper
      elevation={0}
      className={s.categories}
    >
      {
        categoriesByGroup[activeGroup].map((category: string) => {
          const allView = countAllByGroup[activeGroup][category].count;
          const allByFilter = countFilteredByGroup[activeGroup]?.[category]?.count;

          if (!allByFilter) {
            return null;
          }

          return (
            <Category
              key={category}
              category={category}
              allView={allView}
              checkedView={countAllByGroup[activeGroup][category].checked}
              allByFilter={allView !== allByFilter ? allByFilter : null}
              checkedByFilter={countFilteredByGroup[activeGroup]?.[category]?.checked}
            />
          );
        })
      }
    </Paper>
  );
};

const mapStore = ({EldenRingStore}) => {
  return {
    activeGroup: EldenRingStore.activeGroup,
    categoriesByGroup: EldenRingStore.categoriesByGroup,
    countAllByGroup: EldenRingStore.countAllByGroup,
    countFilteredByGroup: EldenRingStore.countFilteredByGroup
  };
};

export default magic(Categories, {store: mapStore, styles: s});
