import React from 'react';
import {ROUTES} from '@utils';
import {
  AuthPage,
  NotFoundPage,
  EldenRingTracking
} from '@views';

const authRoutes = [{
  path: ROUTES.MAIN,
  element: <EldenRingTracking />
}];

const publicRoutes = [
  {
    path: ROUTES.SIGN_IN,
    element: <AuthPage />
  },
  {
    path: ROUTES.SIGN_UP,
    element: <AuthPage />
  },
  {
    path: ROUTES.NOT_FOUND_404,
    element: <NotFoundPage />
  }
];

export {
  authRoutes,
  publicRoutes
};