import {makeObservable, observable, action} from 'mobx';
import {onAuthStateChanged, signOut} from 'firebase/auth';
import {signUp, signIn} from '@api';
import {auth} from '../firebase';
import {notify, FIREBASE_ERRORS} from '@utils';
import {User} from '@firebase/auth';

export default class UserStore {
  email: string = '';
  password: string = '';
  showPassword: boolean = false;
  isLogin: boolean = true;
  user: User | null = null;
  loading: boolean = true;

  constructor() {
    makeObservable(this, {
      email: observable,
      password: observable,
      showPassword: observable,
      isLogin: observable,
      user: observable,
      loading: observable,

      setEmail: action,
      setPassword: action,
      toggleShowPassword: action,
      setIsLogin: action,
      setUser: action,
      setLoading: action
    });
  }

  setEmail = ({target}) => {
    this.email = target.value;
  };

  setPassword = ({target}) => {
    this.password = target.value;
  };

  toggleShowPassword = () => {
    this.showPassword = !this.showPassword;
  };

  setIsLogin = (bool: boolean) => {
    this.isLogin = bool;
  };

  setUser = (user: User | null) => {
    this.user = user;
  };

  setLoading = (state: boolean) => {
    this.loading = state;
  };

  reset = () => {
    this.setEmail({target: ''});
    this.setPassword({target: ''});
  };

  submit = async() => {
    const {
      email,
      password,
      isLogin
    } = this;

    if (!email.trim() || !password.trim()) {
      return notify({
        variant: 'error',
        message: 'Необходимо ввести email и пароль'
      });
    }

    this.setLoading(true);

    try {
      if (isLogin) {
        const user = await signIn(email, password);

        this.setUser(user);
        this.reset();

        return this.setLoading(false);
      }

      const user = await signUp(email, password);

      this.setUser(user);
      this.reset();
      this.setLoading(false);
    } catch(err) {
      this.setLoading(false);
      this.errorHandler(err);
    }
  };

  checkAuth = () => {
    onAuthStateChanged(auth, (user) => {
      this.setUser(user);
      this.setLoading(false);

      return user;
    });
  };

  logOut = () => signOut(auth);

  errorHandler = (error: {code: string, message: string}) => {
    if (!error.code) {
      return notify({
        variant: 'error',
        message: `Во время ${this.isLogin ? 'авторизации' : 'регистрации'} произошла ошибка`
      });
    }

    const errorMessage = FIREBASE_ERRORS[error.code];

    if (errorMessage) {
      return notify({
        variant: 'error',
        message: errorMessage
      });
    }

    return notify({
      variant: 'error',
      message: `${error.code}: ${error.message}`
    });
  };
}