import React from 'react';
import {magic} from '@utils';
import {Fab} from '@mui/material';
import {
  Brightness7 as Sun,
  Brightness4 as Moon
} from '@mui/icons-material';

const ThemeToggle = ({mode, toggleMode}: ThemeToggleProps) => (
  <Fab
    size={'small'}
    color={'primary'}
    aria-label={'themeToggle'}
    onClick={toggleMode}
    sx={
      {
        position: 'absolute',
        top: '1rem',
        left: '1rem'
      }
    }
  >
    {
      mode === 'dark' ?
        <Sun /> :
        <Moon />
    }
  </Fab>
);

const mapStore = ({UiStore}) => {
  return {
    mode: UiStore.mode,
    toggleMode: UiStore.toggleMode
  };
};

type ThemeToggleProps = {
  mode: 'dark' | 'light';
  toggleMode: () => void;
}

export default magic(ThemeToggle, {store: mapStore});