import React from 'react';
import {magic} from '@utils';
import FilterButton from './FilterButton';
import cn from 'classnames';
import s from './Filter.scss';

const buttons = [
  {
    name: 'hideChecked',
    iconName: 'check',
    tooltip: 'checked items'
  },
  {
    name: 'hideDlc',
    iconName: 'plus',
    tooltip: 'DLC items'
  },
  {
    name: 'hidePurchaseFrom',
    iconName: 'dollar-sign',
    tooltip: 'purchased items'
  },
  {
    name: 'hideRewardByNpc',
    iconName: 'circle-question',
    tooltip: 'quest rewards'
  },
  {
    name: 'hideFoundAt',
    iconName: 'location-dot',
    tooltip: 'gatherable items'
  },
  {
    name: 'hideDropByEnemies',
    iconName: 'sword',
    tooltip: 'items with drop chance'
  },
  {
    name: 'hideAlwaysDrop',
    iconName: 'swords',
    tooltip: '100% drop items'
  },
  {
    name: 'hideMissable',
    iconName: 'fire',
    tooltip: 'missable items'
  },
  {
    name: 'hideCrafted',
    iconName: 'hammer',
    tooltip: 'craftable items'
  },
  {
    name: 'hideObtained',
    iconName: 'book',
    tooltip: 'obtainables items'
  }
];

const FilterButtons = ({filter, setFilterValue}) =>
  buttons.map(({name, iconName, tooltip}) => {
    const value = filter[name];

    return (
      <FilterButton
        key={name}
        tooltip={`${value ? 'Show' : 'Hide'} ${tooltip}`}
        iconName={iconName}
        onClick={() => setFilterValue(name, !value)}
        className={cn(s[name], {[s.button]: value})}
      />
    );
  });

const mapStore = ({EldenRingStore}) => {
  return {
    filter: EldenRingStore.filter,
    setFilterValue: EldenRingStore.setFilterValue
  };
};

export default magic(FilterButtons, {store: mapStore, styles: s});