import React from 'react';
import {IconButton, Tooltip} from '@mui/material';
import {Icon} from '@ui';

interface FilterButtonProps {
  tooltip: string;
  iconName: string;
  onClick: () => void;
  className?: string;
}

const FilterButton = ({tooltip, iconName, onClick, className}: FilterButtonProps) => (
  <Tooltip title={tooltip}>
    <IconButton onClick={onClick}>
      <Icon
        type={'solid'}
        name={iconName}
        size={16}
        className={className}
      />
    </IconButton>
  </Tooltip>
);

export default FilterButton;