import React from 'react';
import {magic} from '@utils';
import {TextField, Combobox} from '@ui';
import {Box, Paper} from '@mui/material';
import FilterButtons from './FilterButtons';
import FilterButton from './FilterButton';
import s from './Filter.scss';

const Filter = ({
  groups,
  categories,
  regions,
  filter,
  setFilterValue,
  getFromDatabase,
  saveToDataBase
}) => (
  <Paper
    elevation={0}
    className={s.filter}
  >
    <Combobox
      name={'Group'}
      value={filter.group || []}
      onChange={({target}) => setFilterValue('group', target.value)}
      options={groups}
      isMulti={true}
    />
    <Combobox
      name={'Category'}
      value={filter.category || []}
      onChange={({target}) => setFilterValue('category', target.value)}
      options={categories}
      isMulti={true}
    />
    <Combobox
      name={'Region'}
      value={filter.region || []}
      onChange={({target}) => setFilterValue('region', target.value)}
      options={regions}
      isMulti={true}
    />
    <TextField
      value={filter.name || ''}
      onChange={({target}) => setFilterValue('name', target.value)}
      fullWidth={true}
      placeholder={'Search by name'}
    />
    <Box className={s.bottom}>
      <Box className={s.buttons}>
        <FilterButtons />
      </Box>
      <Box className={s.buttons}>
        <FilterButton
          tooltip={'Download data from DB'}
          iconName={'cloud-arrow-down'}
          onClick={getFromDatabase}
        />
        <FilterButton
          tooltip={'Save data to DB'}
          iconName={'cloud-arrow-up'}
          onClick={saveToDataBase}
        />
      </Box>
    </Box>
  </Paper>
);

const mapStore = ({EldenRingStore}) => {
  return {
    groups: EldenRingStore.groups,
    categories: EldenRingStore.categories,
    regions: EldenRingStore.regions,
    filter: EldenRingStore.filter,
    setFilterValue: EldenRingStore.setFilterValue,
    getFromDatabase: EldenRingStore.getFromDatabase,
    saveToDataBase: EldenRingStore.saveToDataBase
  };
};

export default magic(Filter, {store: mapStore, styles: s});