import React from 'react';
import {hasValue, magic} from '@utils';
import {Box, Tooltip, Typography} from '@mui/material';
import s from './Statistic.scss';

const Stat = ({title, received, all}) => {
  if (!hasValue(all)) {
    return null;
  }

  return (
    <Box className={s.statistic}>
      <Typography className={s.info}>
        {`${title}:`}
      </Typography>
      <Tooltip title={'All'}>
        <Typography className={s.all}>
          {all}
        </Typography>
      </Tooltip>
      <Typography className={s.divider}>
        {'|'}
      </Typography>
      <Tooltip title={'Received'}>
        <Typography className={s.received}>
          {received}
        </Typography>
      </Tooltip>
      <Typography className={s.divider}>
        {'|'}
      </Typography>
      <Typography className={s.percent}>
        {`${(received / all * 100).toFixed()}%`}
      </Typography>
    </Box>
  );
};

export default magic(Stat, {styles: s});