import React from 'react';
import {magic} from '@utils';
import {createTheme, ThemeProvider as MUIThemeProvider} from '@mui/material/styles';
import {CssBaseline} from '@mui/material';

const COLORS = {
  pink: {
    light: '#f16db5',
    main: '#ef56a9',
    dark: '#ed3e9d'
  },
  red: {
    light: '#f8646c',
    main: '#f74c55',
    dark: '#f6333e'
  },
  volcano: {
    light: '#fb8760',
    main: '#fa7447',
    dark: '#fa612e'
  },
  orange: {
    light: '#fbae5b',
    main: '#faa242',
    dark: '#fa9529'
  },
  gold: {
    light: '#fbc55a',
    main: '#fabc41',
    dark: '#fab328'
  },
  yellow: {
    light: '#fced89',
    main: '#fbe970',
    dark: '#fbe557'
  },
  lime: {
    light: '#bce458',
    main: '#b3e042',
    dark: '#aadd2c'
  },
  green: {
    light: '#85d55e',
    main: '#76d04a',
    dark: '#66ca36'
  },
  cyan: {
    light: '#89e0e0',
    main: '#75dbdb',
    dark: '#61d5d5'
  },
  blue: {
    light: '#74bcff',
    main: '#5ab0ff',
    dark: '#41a3ff'
  },
  deepblue: {
    light: '#6d87f1',
    main: '#5674ef',
    dark: '#3e61ed'
  },
  purple: {
    light: '#aa81e3',
    main: '#9c6cde',
    dark: '#8e57da'
  },
  white: '#ddd',
  black: '#000',
  pureWhite: '#fff',
  gray: '#aaa',
  contrastText: '#010102'
};

const ThemeProvider = ({mode, children}: ThemeProviderProps) => {
  const variables = {
    palette: {
      mode,
      primary: {
        light: COLORS.deepblue.light,
        main: COLORS.deepblue.main,
        dark: COLORS.deepblue.dark,
        contrastText: COLORS.contrastText
      },
      secondary: {
        light: COLORS.gold.light,
        main: COLORS.gold.main,
        dark: COLORS.gold.dark,
        contrastText: COLORS.contrastText
      },
      error: {
        light: COLORS.red.light,
        main: COLORS.red.main,
        dark: COLORS.red.dark,
        contrastText: COLORS.contrastText
      },
      warning: {
        light: COLORS.gold.light,
        main: COLORS.gold.main,
        dark: COLORS.gold.dark,
        contrastText: COLORS.contrastText
      },
      info: {
        light: COLORS.blue.light,
        main: COLORS.blue.main,
        dark: COLORS.blue.dark,
        contrastText: COLORS.contrastText
      },
      success: {
        light: COLORS.green.light,
        main: COLORS.green.main,
        dark: COLORS.green.dark,
        contrastText: COLORS.contrastText
      },
      background: {
        paper: mode === 'dark' ? '#0f0f11' : '',
        default: mode === 'dark' ? '#1d1e20' : '#fff'
      },
      text: {
        primary: mode === 'dark' ? '#a2a2a2' : COLORS.contrastText
      }
    }
  };

  const theme = React.useMemo(() => createTheme(variables), [mode]);

  return (
    <MUIThemeProvider theme={theme}>
      <CssBaseline />
      {children}
    </MUIThemeProvider>
  );
};

const mapStore = ({UiStore}) => {
  return {
    mode: UiStore.mode
  };
};

type ThemeProviderProps = {
  mode: 'dark' | 'light';
  children: React.ReactNode;
};

export default magic(ThemeProvider, {store: mapStore});