'use strict';

/**
 * Каррирование функции
 * @param {function} fn - функция, которую необходимо каррировать
 * @example
 * const sum = (a, b) => a + b;
 * const curriedSum = curry(sum);
 * const plusOne = curriedSum(1);
 *
 * plusOne(2); // 3
 * curriedSum(1, 2); // 3
 * curriedSum(1)(2); // 3
 * @description
 * Каррирование - это трансформация функции,
 * чтобы она принимала аргументы
 * не как f(a, b, c), а как f(a)(b)(c).
 */
const curry = (fn) =>
  function curried(...args) {
    if (args.length < fn.length) {
      return curried.bind(null, ...args);
    }

    /* eslint-disable no-useless-call */
    return fn.call(null, ...args);
  };

/**
 * Достаёт значение из объекта по свойству `field`
 * @param {string} field - Наименование свойства, значение которого необходимо вернуть
 * @param {Object} object - Объект, из которого необходимо вернуть свойства
 * @returns {*} - Значение свойства
 * @example
 * const object = {
 *   id: 1,
 *   name: 'objectName',
 *   params: {
 *     param1: 'value',
 *     param2: 'value2'
 *   }
 * };
 *
 * prop('params', object); // { param1: 'value', param2: 'value2' }
 * prop('title', object); // undefined
 */
const prop = curry((field, object) => object[field]);

/**
 * Возвращает объект без свойств которые описаны в `fields`
 * @param {string[]} fields - Спиоск свойств, которые необходимо убрать
 * @param {Object} object - Объект, из которого необходимо убрать свойства
 * @returns {Object} - Измененный объект
 * @example
 * const object = {
 *   id: 1,
 *   name: 'objectName',
 *   params: {
 *     param1: 'value',
 *     param2: 'value2'
 *   }
 * };
 *
 * omit(['params'], object); // { id: 1, name: 'objectName' }
 */
const omit = curry((fields, object) => {
  const entries = Object
    .entries(object)
    .filter((entry) => !fields.includes(entry[0]));

  return Object.fromEntries(entries);
});

/**
 * Возвращает объект со свойствами которые описаны в `fields`
 * @param {string[]} fields - Спиоск свойств, которые необходимо убрать
 * @param {Object} object - Объект, из которого необходимо убрать свойства
 * @returns {Object} - Измененный объект
 * @example
 * const object = {
 *   id: 1,
 *   name: 'objectName',
 *   params: {
 *     param1: 'value',
 *     param2: 'value2'
 *   }
 * };
 *
 * pick(['id', 'name'], object); // { id: 1, name: 'objectName' }
 */
const pick = curry((fields, object) =>
  fields.reduce((acc, item) => {
    acc[item] = object[item];

    return acc;
  }, {}));

export {
  prop,
  omit,
  pick
};