import React from 'react';
import {TextField} from '@mui/material';
import {IAnyObject} from '@types';

const TextFieldView = ({name, value, onChange, placeholder, fullWidth}: TextFieldViewProps) => (
  <TextField
    name={name}
    value={value}
    onChange={onChange}
    placeholder={placeholder}
    fullWidth={fullWidth}
    size={'small'}
  />
);

type TextFieldViewProps = {
  name?: string;
  value: string;
  onChange: ({target}: IAnyObject) => void,
  placeholder?: string;
  fullWidth?: boolean;
}

export default TextFieldView;