export const keyboardConvert = (string: string): string[] => {
  const variants = new Set([string]);

  for (const replacer of replacers) {
    const converted = replacer(string);

    if (converted !== string) {
      variants.add(converted);
    }
  }

  return [...variants];
};

const enToRu: Record<string, string> = {
  'q': 'й', 'w': 'ц', 'e': 'у', 'r': 'к', 't': 'е', 'y': 'н', 'u': 'г', 'i': 'ш',
  'o': 'щ', 'p': 'з', '[': 'х', ']': 'ъ', 'a': 'ф', 's': 'ы', 'd': 'в', 'f': 'а',
  'g': 'п', 'h': 'р', 'j': 'о', 'k': 'л', 'l': 'д', ';': 'ж', "'": 'э', 'z': 'я',
  'x': 'ч', 'c': 'с', 'v': 'м', 'b': 'и', 'n': 'т', 'm': 'ь', ',': 'б', '.': 'ю',
  '`': 'ё', 'Q': 'Й', 'W': 'Ц', 'E': 'У', 'R': 'К', 'T': 'Е', 'Y': 'Н', 'U': 'Г',
  'I': 'Ш', 'O': 'Щ', 'P': 'З', '{': 'Х', '}': 'Ъ', 'A': 'Ф', 'S': 'Ы', 'D': 'В',
  'F': 'А', 'G': 'П', 'H': 'Р', 'J': 'О', 'K': 'Л', 'L': 'Д', ':': 'Ж', '"': 'Э',
  'Z': 'Я', 'X': 'Ч', 'C': 'С', 'V': 'М', 'B': 'И', 'N': 'Т', 'M': 'Ь', '<': 'Б',
  '>': 'Ю', '~': 'Ё'
};

const ruToEn: Record<string, string> = Object.fromEntries(
  Object
    .entries(enToRu)
    .map(([en, ru]) => [ru, en])
);

const createReplacer = (replaceMap: Record<string, string>) => {
  const pattern = new RegExp(`[${Object.keys(replaceMap).join('')}]`, 'g');

  return (str: string) => str.replace(pattern, char => replaceMap[char]);
};

const replacers = [
  createReplacer(enToRu),
  createReplacer(ruToEn)
];