import React from 'react';
import {magic} from '@utils';
import {Paper, Box} from '@mui/material';
import List from './List';
import s from './Items.scss';

const Items = ({filter, checked, categoryItems}) => {
  if (filter.hideChecked && categoryItems.every(({name}) => checked.has(name))) {
    return (
      <Paper
        elevation={0}
        className={s.items}
      >
        <Box className={s.nothing}>
          {'Nothing found by this filter'}
        </Box>
      </Paper>
    );
  }

  return <List />;
};

const mapStore = ({EldenRingStore}) => {
  return {
    filter: EldenRingStore.filter,
    checked: EldenRingStore.checked,
    categoryItems: EldenRingStore.categoryItems
  };
};

export default magic(Items, {store: mapStore, styles: s});