import React from 'react';
import {magic} from '@utils';
import {
  Checkbox,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText
} from '@mui/material';
import Actions from './Actions';
import s from './Items.scss';

const Item = ({item, filter, checked, setCheckValue, link}) => {
  const hasChecked = checked.has(item.name);

  if (filter.hideChecked && hasChecked) {
    return null;
  }

  return (
    <ListItem disablePadding={true}>
      <ListItemButton
        className={s.item}
        dense={true}
      >
        <ListItemIcon>
          <Checkbox
            className={s.checkbox}
            name={item.name}
            checked={hasChecked}
            onClick={setCheckValue}
            edge={'start'}
            disableRipple={true}
          />
        </ListItemIcon>
        <ListItemText
          primary={
            (
              <Actions
                item={item}
                hasChecked={hasChecked}
                link={link(item.href || item.name)}
              />
            )
          }
        />
      </ListItemButton>
    </ListItem>
  );
};

const mapStore = ({EldenRingStore}) => {
  return {
    filter: EldenRingStore.filter,
    checked: EldenRingStore.checked,
    link: EldenRingStore.link
  };
};

export default magic(Item, {store: mapStore});