import React from 'react';
import {magic} from '@utils';
import Link from '../Link';
import s from '../Items.scss';

const Row = ({linkable, info, link}) => {
  if (linkable) {
    return (
      <p>
        <Link
          name={info}
          href={link(info)}
          className={s.link}
        />
      </p>
    );
  }

  return (
    <p className={s.tooltipDesc}>
      {info}
    </p>
  );
};

const mapStore = ({EldenRingStore}) => {
  return {
    link: EldenRingStore.link
  };
};

export default magic(Row, {store: mapStore, styles: s});
