import React from 'react';
import Row from './Row';

const Description = ({linkable, data}) => {
  if (!data) {
    return null;
  }

  return Array.isArray(data) ?
    data.map((info) => (
      <Row
        key={info}
        info={info}
        linkable={linkable}
      />
    )) : (
      <Row
        info={data}
        linkable={linkable}
      />
    );
};

export default Description;