import React from 'react';
import {magic} from '@utils';
import {Box} from '@mui/material';
import Stat from './Stat';
import s from './Statistic.scss';

const Statistic = ({received, receivedAll, filtered, all}) => (
  <Box className={s.container}>
    <Stat
      title={'Total'}
      received={receivedAll}
      all={all}
    />
    <Stat
      title={'By Filter'}
      received={received}
      all={filtered}
    />
  </Box>
);

export default magic(Statistic, {styles: s});