import React from 'react';
import {magic} from '@utils';
import {Paper} from '@mui/material';
import Item from './Item.tsx';
import s from './Items.scss';

const List = ({setCheckValue, categoryItems}) => {
  const handleCheck = (event) => {
    event.stopPropagation();

    setCheckValue(event);
  };

  const [visibleItems, setVisibleItems] = React.useState([]);

  React.useEffect(() => {
    let index = 0;

    const chunkSize = 25;

    setVisibleItems([]);

    const loadBatch = () => {
      const nextBatch = categoryItems.slice(index, index + chunkSize);

      setVisibleItems(prev => [...prev, ...nextBatch]);

      index += chunkSize;

      if (index < categoryItems.length) {
        requestAnimationFrame(loadBatch);
      }
    };

    loadBatch();
  }, [categoryItems]);

  return (
    <Paper
      elevation={0}
      className={s.items}
    >
      {
        visibleItems.map((item) => (
          <Item
            key={item.name}
            item={item}
            setCheckValue={handleCheck}
          />
        ))
      }
    </Paper>
  );
};

const mapStore = ({EldenRingStore}) => {
  return {
    filter: EldenRingStore.filter,
    checked: EldenRingStore.checked,
    categoryItems: EldenRingStore.categoryItems,
    setCheckValue: EldenRingStore.setCheckValue
  };
};

export default magic(List, {store: mapStore, styles: s});