import React from 'react';
import {magic} from '@utils';
import {Box, Typography} from '@mui/material';
import Statistic from '../Statistic';
import cn from 'classnames';
import s from './Categories.scss';

const Category = ({
  category,
  allView,
  checkedView,
  allByFilter,
  checkedByFilter,
  activeCategory,
  setActiveCategory
}) => {
  const classNames = cn({[s.active]: category === activeCategory}, s.button);

  return (
    <Box
      className={classNames}
      onClick={() => setActiveCategory(category)}
    >
      <Typography className={s.categoryName}>
        {category}
      </Typography>
      <Statistic
        received={checkedByFilter}
        receivedAll={checkedView}
        filtered={allByFilter}
        all={allView}
      />
    </Box>
  );
};

const mapStore = ({EldenRingStore}) => {
  return {
    activeCategory: EldenRingStore.activeCategory,
    setActiveCategory: EldenRingStore.setActiveCategory
  };
};

export default magic(Category, {store: mapStore, styles: s});
